-- Title: iam get_session_context multi-tenant
-- Kind: patch
-- Intent: iam_get_session_context_multi_tenant
-- Context: TH-01 — user với ≥2 memberships active không còn raise CONTEXT_INVALID khi
-- Touches: iam.get_session_context
-- 3-B (2026-10-11): KI-05 — bootstrap_owner removed; the default store is created with the tenant (iam._create_tenant_for_owner).
-- Safety: idempotent ; medium
-- Depends on: 20260830001_iam_active_store_context_group_a.sql, 20260811024_iam_patch_owner_role_canonicalization.sql
-- Promoted from _drafts/019_iam_get_session_context_multi_tenant.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.get_session_context(p_tenant_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid;
  v_role text;
  v_status text;
  v_is_owner boolean;
  v_active_count int;
  v_active_store_id uuid;
  v_active_store_code text;
  v_active_store_display_name text;
  v_permissions text[];
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"NOT_AUTHENTICATED","message":"Not authenticated.","details":{}}';
  end if;

  if p_tenant_id is not null then
    select m.tenant_id, m.role, iam._membership_status_code(m.is_active, m.removed_at), coalesce(m.is_owner, false)
    into v_tenant_id, v_role, v_status, v_is_owner
    from iam.memberships m
    where m.user_id = v_user_id
      and m.tenant_id = p_tenant_id;

    if v_tenant_id is null then
      raise exception using errcode = 'P0001',
        message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
    end if;
    if v_status = 'inactive' then
      raise exception using errcode = 'P0001',
        message = '{"code":"MEMBERSHIP_INACTIVE","message":"Membership is inactive.","details":{}}';
    end if;
    if v_status = 'removed' then
      raise exception using errcode = 'P0001',
        message = '{"code":"MEMBERSHIP_REMOVED","message":"Membership is removed.","details":{}}';
    end if;
    if coalesce(v_status, 'active') <> 'active' then
      raise exception using errcode = 'P0001',
        message = '{"code":"TENANT_ACCESS_DENIED","message":"Tenant access denied.","details":{}}';
    end if;
  else
    select count(*)::int
    into v_active_count
    from iam.memberships m
    where m.user_id = v_user_id
      and m.is_active;

    -- Ambiguous / empty: caller must pick tenant explicitly (multi-tenant UX).
    if coalesce(v_active_count, 0) = 0 or v_active_count > 1 then
      return null;
    end if;

    select m.tenant_id, m.role, iam._membership_status_code(m.is_active, m.removed_at), coalesce(m.is_owner, false)
    into v_tenant_id, v_role, v_status, v_is_owner
    from iam.memberships m
    where m.user_id = v_user_id
      and m.is_active
    order by m.created_at
    limit 1;
  end if;

  -- Single-store era: the tenant's active store (default first) is the active store.
  select store.id
  into v_active_store_id
  from iam.stores store
  where store.tenant_id = v_tenant_id
    and store.status = 'active'
  order by (store.code = 'default') desc, store.created_at, store.id
  limit 1;

  if v_active_store_id is null
    or not iam.can_access_store(v_tenant_id, v_active_store_id, v_user_id) then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Exactly one active default store is required.","details":{}}';
  end if;

  select store.code, store.display_name
  into v_active_store_code, v_active_store_display_name
  from iam.stores store
  where store.tenant_id = v_tenant_id
    and store.id = v_active_store_id
    and store.status = 'active';

  if v_active_store_code is null or v_active_store_display_name is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Active store identity is required.","details":{}}';
  end if;

  if coalesce(v_is_owner, false) then
    v_permissions := array[]::text[];
  else
    select coalesce(array_agg(rp.permission order by rp.permission), array[]::text[])
    into v_permissions
    from iam.role_permissions rp
    where rp.role = v_role;
  end if;

  return jsonb_build_object(
    'user_id', v_user_id,
    'tenant_id', v_tenant_id,
    'active_store_id', v_active_store_id,
    'active_store_code', v_active_store_code,
    'active_store_display_name', v_active_store_display_name,
    'role', v_role,
    'is_owner', coalesce(v_is_owner, false),
    'permissions', to_jsonb(v_permissions)
  );
end;
$$;

revoke all on function iam.get_session_context(uuid) from public, anon;
grant execute on function iam.get_session_context(uuid) to authenticated;
